from flask import Flask, abort

app = Flask(__name__)
app.config['TESTING'] = True
PROGRESS = {3: 75}

@app.get('/progress/<int:lesson_id>')
def get_progress(lesson_id):
    if lesson_id not in PROGRESS:
        abort(404)
    return {'lesson_id': lesson_id, 'percent': PROGRESS[lesson_id]}

client = app.test_client()
known = client.get('/progress/3')
unknown = client.get('/progress/4')
assert known.status_code == 200
assert known.json == {'lesson_id': 3, 'percent': 75}
assert unknown.status_code == 404
print(known.json, unknown.status_code)
